pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(actor != address(0));
        blockNum = bound(blockNum, 1, type(uint48).max);

        vm.roll(blockNum);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Reference rule: the balance is drained exactly on blocks divisible by 15,
        // otherwise the contract still holds its initial 10 ether.
        assertTrue(
            block.number % 15 == 0 ? address(c).balance == 0 : address(c).balance == 10 ether
        );
    }
}

