import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 n, uint256 t, address actor) public {
        vm.assume(t > 0);
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(actor.code.length == 0); // EOA so the payout transfer always succeeds
        n = bound(n, 1, type(uint256).max / 2);

