pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }
    function testFuzz_property(uint256 blockNumber, uint256 ts, address actor) public {
        // admissible domain: any block, any timestamp after genesis, actor must be a
        // plain recipient able to receive the payout via transfer (EOA-like address)
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(actor.code.length == 0);
        ts = bound(ts, 1, type(uint256).max);
        vm.roll(blockNumber);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok); // reference never reverts on admissible inputs

        if (blockNumber % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 10 ether);
        }
    }
}

