contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount != 10 ether);
        vm.assume(amount <= actor.balance + 1e30);
        vm.assume(actor != address(c));
        vm.deal(actor, amount + 1 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a call with msg.value != 10 ether must never succeed.
        assertTrue(!ok);
    }
