        // first call: succeeds (timestamp t > pastBlockTime 0)
        vm.prank(actor);
        c.f{value: 10 ether}();

        // second call in the same block/timestamp: reference MUST revert
        vm.prank(actor);
        bool ok;
        try c.f{value: 10 ether}() { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

